package com.shazwan.idash;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import java.util.*;
/** Settings-only actions. Existing dock, media and system-control implementations are untouched. */
final class SettingsActions {
 final LauncherActivity a;final DashSettings screen;
 SettingsActions(LauncherActivity a,DashSettings screen){this.a=a;this.screen=screen;}
 boolean installed(String component){try{ComponentName name=ComponentName.unflattenFromString(component);if(name==null)return false;ActivityInfo info=a.getPackageManager().getActivityInfo(name,0);return info.enabled&&info.applicationInfo.enabled&&info.exported&&(info.permission==null||a.checkSelfPermission(info.permission)==PackageManager.PERMISSION_GRANTED)&&new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(name).resolveActivity(a.getPackageManager())!=null;}catch(PackageManager.NameNotFoundException|RuntimeException absent){return false;}}
 String favorite(int slot){String saved=a.prefs.getString("favorite_"+a.slots[slot],"");if(saved.isEmpty())return "Belum dipilih";if(!installed(saved))return "Aplikasi tiada · pilih semula";LauncherActivity.App app=a.assigned(slot);return app==null?ComponentName.unflattenFromString(saved).getPackageName():app.label;}
 void chooseApp(int slot){if(!a.loaded){Toast.makeText(a,"Senarai aplikasi sedang dimuatkan",Toast.LENGTH_SHORT).show();return;}ArrayList<LauncherActivity.App> apps=new ArrayList<>();for(LauncherActivity.App app:a.apps)if(installed(app.component))apps.add(app);String[] labels=new String[apps.size()+1];labels[0]="Kosongkan pilihan";for(int i=0;i<apps.size();i++)labels[i+1]=apps.get(i).label;
  screen.dialog=new AlertDialog.Builder(a).setTitle("Aplikasi "+a.slots[slot]).setItems(labels,(d,index)->{if(index==0){a.prefs.edit().putString("favorite_"+a.slots[slot],"").apply();a.render();return;}select(slot,apps.get(index-1));}).setNeutralButton("Segar semula",(d,w)->a.loadApps()).setNegativeButton("Batal",null).show();
 }
 boolean select(int slot,LauncherActivity.App app){if(slot<0||slot>=a.slots.length||app==null||!installed(app.component)){Toast.makeText(a,"Aplikasi tidak lagi tersedia. Pilihan lama dikekalkan.",Toast.LENGTH_LONG).show();return false;}a.assign(slot,app);return true;}
 void launch(Intent intent){if(intent==null){Toast.makeText(a,"Aplikasi tidak tersedia",Toast.LENGTH_SHORT).show();return;}try{a.startActivity(intent);}catch(ActivityNotFoundException|SecurityException unavailable){Toast.makeText(a,"Aplikasi tidak tersedia atau akses ditolak",Toast.LENGTH_LONG).show();}}
 void permissions(){screen.dialog=new AlertDialog.Builder(a).setTitle("Akses Android").setItems(new String[]{"Info aplikasi / Nearby devices","Akses kecerahan","Akses media","Akses Focus / DND"},(d,index)->{if(index==0)launch(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.getPackageName())));else if(index==1)launch(new Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS,Uri.parse("package:"+a.getPackageName())));else if(index==2)screen.dialog=new AlertDialog.Builder(a).setTitle("Akses media").setMessage("Android memerlukan Notification Listener Access untuk menemui MediaSession aplikasi lain. Akses ini luas dan boleh mendedahkan notifikasi. iDash menggunakan metadata serta kawalan media sahaja; ia tidak membaca atau menyimpan kandungan notifikasi.").setNegativeButton("Batal",null).setPositiveButton("Buka akses",(x,w)->a.openSettings(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)).show();else screen.dialog=new AlertDialog.Builder(a).setTitle("Akses Focus / DND").setMessage("Notification Policy Access membolehkan kawalan DND selepas anda memilih mod Focus. Membuka Settings tidak mengubah DND.").setNegativeButton("Batal",null).setPositiveButton("Buka akses",(x,w)->a.openSettings(Settings.ACTION_NOTIFICATION_POLICY_ACCESS_SETTINGS)).show();}).setNegativeButton("Tutup",null).show();}
 void reset(){screen.dialog=new AlertDialog.Builder(a).setTitle("Reset Settings iDash?").setMessage("Akan direset: Appearance, pilihan wallpaper, widget, jam, profil dock, aplikasi kegemaran, zon JAKIM dan mod Panel.\n\nDikekalkan: fail imej peribadi, cache jadual JAKIM, preset/diagnostik FM dan data companion. Aplikasi lain tidak dipadam. Pilihan aplikasi dock akan kembali kepada nilai lalai selepas pelancaran semula.").setNegativeButton("Batal",null).setPositiveButton("Reset",(d,w)->{a.prefs.edit().clear().apply();a.recreate();}).show();}
 String accessStatus(){try{NotificationManager n=(NotificationManager)a.getSystemService(Context.NOTIFICATION_SERVICE);return "Kecerahan: "+(Settings.System.canWrite(a)?"dibenarkan":"akses diperlukan")+"\nMedia: "+(android.os.Build.VERSION.SDK_INT>=27&&n!=null&&n.isNotificationListenerAccessGranted(new ComponentName(a,MediaAccessService.class))?"dibenarkan":"akses diperlukan")+"\nDND: "+(n!=null&&n.isNotificationPolicyAccessGranted()?"dibenarkan":"akses diperlukan");}catch(RuntimeException unsupported){return "Status akses tidak tersedia pada ROM ini";}}
}
